<script setup>
import { onMounted, onBeforeUnmount, ref, inject, computed } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';
import { globalSearch } from '@/components/reusables/globalSearch';
    const approval_transactions_columns = ref(['Sno','ref_no','issuer','host','amount','direction','target_account','attachment','date','actions']);    
    const receipt_columns = ref(['Sno','registrar','attachment','date']);   

const filter = ref('')

useMeta({ title: 'Approval Chains' });
 import { useRoute } from 'vue-router';
const route = useRoute();
const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL
});
import { watch } from 'vue';
const complete_transaction = ref(false)
const completeTransaction = async (id)=>{
  const payload = {
    status_id : 16,
    remark : remark.value
  }
  try{
        loading.value = true
    const response = await axiosInstance.put(`approval-lists/${id}`,payload)
    showMessage('Transaction Completed')
   getApprovalItems()
   remark.value = ''
   complete_transaction.value = false
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value = false
  }
}

const create_approval = ref(false)
const toggleApproval = ()=>{
  create_approval.value =! create_approval.value
}

const beneficiary = ref('')
const description = ref('')

const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const spinner = ref(false);
const user_id = JSON.parse(localStorage.getItem("user")).id
const total_amount = ref(0);
const user_role_id = ref(JSON.parse(localStorage.getItem('user')).role);
const items = ref([]);
const requisitionItems = ref([]);
const table_option = ref({
  perPage: 50,
  perPageValues: [  50,100,200],
  skin: 'table table-hover table-striped',
  columnsClasses: { actions: 'actions text-center' },
  sortable: ['id', 'service_name'],
  sortIcon: { base: 'sort-icon-none', up: 'sort-icon-asc', down: 'sort-icon-desc' },
  pagination: { nav: 'scroll', chunk: 5 },
  texts: { count: 'Showing {from} to {to} of {count}', filter: '', filterPlaceholder: 'Search...', limit: 'Results:' },
  resizableColumns: false,
  headings: {
    vendor: function() {
      return isBeneficiaryGroup.value ? 'Beneficiary' : 'Vendor';
    }
  }
});



const isBeneficiaryGroup = computed(() => {
  return route.params.group_id == '4' || route.params.group_id == '8';
});




const showMessage = inject('showMessage');
const showError = inject('showError');
const formatNumber = inject('formatNumber');
const tableShimmer = inject('tableShimmer');
const waitIndicator = inject('waitIndicator');
const formatDate = inject('formatDate');
const loadingSpinner = inject('loadingSpinner')
 const enforceMax = inject('enforceMax');
const approvalChain = ref([]);
const awaiter = ref({});
const awaiter_id = ref('');
const item_id = ref('');
const status = ref('')
/** local flag you wanted */
const localChecked = ref(false);

/** modal ref to reset flag when closed */
const approvalModal = ref(null);
let onHidden = null;
const loading = ref(false)



const getApprovalItems = async () => {
 loading.value = true
 getApprovalTransactions(route.params.approval_list_id)
  try {
    const response = await axiosInstance.get(`get-approval-lists?approval_list_id=${route.params.approval_list_id}`);
    items.value = response.data.map((item, index) => {
      let status = item.status;
      if (item.last_checked_in?.status?.id == 4 || item.last_checked_in?.status?.id == 14) {
        status = {
          name: item.last_checked_in.status.name,
          color: item.last_checked_in.status.color
        };
      }

      let awaits = item.awaiting_approval?.name || 'no one';
      if (item.last_checked_in?.status?.id == 4 || item.last_checked_in?.status?.id == 14) {
        awaits = 'no one';
      }

      let awaiter_role_id = item.awaiting_approval?.role_id || null;
      if (item.last_checked_in?.status?.id == 4 || item.last_checked_in?.status?.id == 14) {
        awaiter_role_id = null;
      }

      return {
        ...item,
        status,
        Sno: index + 1,
        group_id : item.group_id,
        purpose: item.approval_group,
        type: item.requisition_type ?? item?.source,
        approval: '0' + item.id,
        approval_id: item.id,
        requisition: item?.requisition_id ?? item?.source_id,
        requester : item.requester?.name ?? item?.requester,
        requester_id : item.requester?.id,
        awaits,
        awaiter_role_id,
        vendor: item.vendor && item.vendor.name ? item.vendor.name : item.beneficiary,
        vendor_data: item.vendor,
        date : formatDate(item.date),
        created_at : item.date,
        last_checked: formatDate(item.last_checked_in?.approved_at),
        cost: item.items
          ? formatNumber(item.items.reduce(
              (sum, i) =>
                sum +
                ((i?.quantity || 0) *
                  (i.requisition_items?.rate || 0)),
              0
            ))
          : 0,
        approved_at: item.last_checked_in?.approved_at
          ? new Date(item.last_checked_in.approved_at).toLocaleString('en-GB', {
              year: 'numeric',
              month: '2-digit',
              day: '2-digit',
              hour: '2-digit',
              minute: '2-digit',
              second: '2-digit'
            })
          : null
      };
    });

    items.value.sort((a, b) => {
      const role = Number(user_role_id.value);
      const aMatch = a.awaiter_role_id === role;
      const bMatch = b.awaiter_role_id === role;

      if (aMatch && !bMatch) return -1;
      if (!aMatch && bMatch) return 1;
      return 0;
    });

  } catch (error) {
    showError(error.message);
    console.error(error);
  } finally {
    loading.value = false
  }
};

const filteredData = computed(()=>{
  return globalSearch(items.value,filter.value)
})


watch(
  () => route.params.group_id,
  (newGroupId, oldGroupId) => {
    if (newGroupId !== oldGroupId) {
      getApprovalGroup()
      getApprovalItems();
    }
  }
);

const lastApprovalRole = ref('')
const requisition_source_item_id = ref(0)
const item_date =  ref('')
const awaits = ref('')
const item = ref('')
const approval_description = ref('')
const approval = ref('')
const getApprovalChain = (row) => {
  approval.value = row
  requisitionItems.value = row.items.map((item, index) => ({
    ...item,
    order_item_id :  item?.requisition_items?.id,
    Sno: index + 1,
    item: item?.requisition_items?.remark,
    description: item?.requisition_items?.description + (item.description ? ' ( ' + item.description + ' )' : ''),
    rate: Number(item?.requisition_items?.rate).toLocaleString() + '/=',
    rate_original :item?.requisition_items?.rate,
    total: (item?.quantity * item?.requisition_items?.rate).toLocaleString() + '/=',
    selected:false,
    rate_original : item?.requisition_items?.rate,
    requesting_quantity : '',
    request_description : ''
  }));

  awaits.value = row.awaits
  approval_description.value = row.approval_description;
  approvalChain.value = (row.roles_sequence || []).slice();
  lastApprovalRole.value = (row.roles_sequence?.length > 0)
