import logo from "@/assets/images/logo.jpg";

const downloadApprovalItem = async (voucher, vendor) => {
  try {
    const totalAmount = voucher.items.reduce(
      (acc, item) =>
        acc + (item.requisition_items?.quantity * item.requisition_items?.rate || 0),
      0
    );

    const today = new Date();
    const date = today.getDate().toString().padStart(2, "0");
    const month = (today.getMonth() + 1).toString().padStart(2, "0");
    const dateString = `${date}/${month}`;

    const doc = new jsPDF("p", "pt", "a4");
    let cursorY = 20;

    const img = new Image();
    img.src = logo;
    img.onload = () => {
      doc.addImage(img, "PNG", 40, cursorY, 160, 50);

    // Voucher Ref box
doc.setDrawColor(0);
doc.rect(480, cursorY, 90, 40); // moved right and reduced size
doc.setFontSize(12);
doc.text("Ref NO:", 500, cursorY + 15);
doc.setTextColor(255, 0, 0);
doc.text(
  `${("0000" + voucher.ref_no).slice(-4)}/${dateString}`,
  500,
  cursorY + 30
);
doc.setTextColor(0);


      doc.setFontSize(10);
      doc.text("TIN: 103-826-519", 400, cursorY + 65);
      doc.text("VRN: 20-01-017530R", 400, cursorY + 80);

      cursorY += 100;

      const pageWidth = doc.internal.pageSize.getWidth();

      doc.setFontSize(16);
      doc.setFont(undefined, "bold");
      doc.text("COPEX CONTRACTORS CO.LTD", pageWidth / 2, cursorY, { align: "center" });
      cursorY += 15;
      doc.setFontSize(10);
      doc.setFont(undefined, "normal");
      doc.text("Msamvu, P.O.BOX 678, Morogoro", pageWidth / 2, cursorY, { align: "center" });
      cursorY += 12;
      doc.text("Mobile: 0713 000 777, 0657 111 555", pageWidth / 2, cursorY, { align: "center" });
      cursorY += 20;

      doc.setFontSize(12);
      doc.setFont(undefined, "bold");
      doc.text(`${voucher.type.toUpperCase()} DETAILS`, pageWidth / 2, cursorY, { align: "center" });
      cursorY += 20;

      doc.autoTable({
        startY: cursorY,
        head: [["Vendor Name", "Location", "Email", "Phone", "Address"]],
        body: [[
          vendor.name || "N/A",
          vendor.location || "N/A",
          vendor.email || "N/A",
          vendor.phone || "N/A",
          vendor.address || "N/A",
        ]],
        theme: "grid",
        headStyles: { fillColor: [248, 248, 248], textColor: 0 },
        styles: { fontSize: 10 },
      });
      cursorY = doc.lastAutoTable.finalY + 15;

      const itemsBody = voucher.items.map((item, i) => [
        i + 1,
        item.requisition_items?.remark || "N/A",
        item.requisition_items?.description || "N/A",
        item.requisition_items?.quantity || 0,
        Number(item.requisition_items?.rate || 0).toLocaleString(),
        ((item.requisition_items?.quantity || 0) * (item.requisition_items?.rate || 0)).toLocaleString(),
      ]);
      itemsBody.push([{ content: "TOTAL", colSpan: 5, styles: { halign: "right", fontStyle: "bold" } }, totalAmount.toLocaleString()]);

      doc.autoTable({
        startY: cursorY,
        head: [["SN", "Item", "Description", "Quantity", "Rate", "Total"]],
        body: itemsBody,
        theme: "grid",
        headStyles: { fillColor: [248, 248, 248], textColor: 0 },
        styles: { fontSize: 10, halign: "center" },
        columnStyles: { 0: { halign: "center" }, 1: { halign: "left" }, 2: { halign: "left" } },
      });
      cursorY = doc.lastAutoTable.finalY + 25;

      doc.setFontSize(12);
      doc.setFont(undefined, "bold");
      doc.text("APPROVAL CHAIN", pageWidth / 2, cursorY, { align: "center" });
      cursorY += 10;

      const approvalHead = voucher.roles_sequence.map(r => r.name || "N/A");
      const approvalBody = [
        voucher.roles_sequence.map(r => ({
          content: r.checked ? "Approved" : "Pending",
          styles: { halign: "center", textColor: r.checked ? [0, 128, 0] : [255, 0, 0] },
        })),
      ];

      doc.autoTable({
        startY: cursorY,
        head: [approvalHead],
        body: approvalBody,
        theme: "grid",
        headStyles: { fillColor: [248, 248, 248], textColor: 0 },
        styles: { fontSize: 10 },
      });

      doc.save(`voucher_${voucher.ref_no}.pdf`);
    };
  } catch (error) {
    console.error(`Failed to generate voucher: ${error.message}`);
    throw error;
  }
};

const approvalGroup = ref('')
const getApprovalGroup = async(groupId = null) => {
  approvalGroup.value = '';
  
  let targetGroupId = groupId;
  if (!targetGroupId && items.value.length > 0) {
    targetGroupId = items.value[0].group_id;
  }
  
  if (!targetGroupId) {
    console.warn('No group ID available for fetching approval group');
    return;
  }
  
  try {
    const response = await axiosInstance.get(`approval-groups/${targetGroupId}`);
    approvalGroup.value = response.data;
  } catch (error) {
    showError(`Failed to fetch approval group: ${error.message}`);
  }
};


    const approvalTransactions = ref([])
    const getApprovalTransactions = async (id) => {
              approvalTransactions.value = []
   try{
      const response = await axiosInstance.get(`account-transactions?approval_id=${id}`)
      approvalTransactions.value = response.data.map((item,index)=>({
    ...item,
    Sno : index + 1,
    attachment :  process.env.VUE_APP_API_BASE_URL+'../../'+ item.attachment,
   amount_raw: parseFloat(item.amount) || 0,
    amount : formatNumber(item.amount),
    date : formatDate(item.date),
    ref_no : item.reference_number,
    issuer : item?.issuer?.name,
    target_account :  (item?.transaction_point?.name ?? '') + ' ' +
  (item?.transaction_point?.mobile_money?.name ?? '') + ' ' +
  (item?.transaction_point?.mobile_money?.category ?? 'CASH')
  }))
   }catch(error){
    showError(error.message)
    console.log(error)
   }finally{

   }

   getReceipts(id)
};

const receipts = ref([])
    const getReceipts = async (id) => {
      receipts.value = []
   try{
      const response = await axiosInstance.get(`purchase-order-receipts?approval_id=${id}`)
      receipts.value = response.data.map((item,index)=>({
    ...item,
    Sno : index + 1,
    attachment :  process.env.VUE_APP_API_BASE_URL+'../../'+ item.attachment,
    date : item.date,
    registrar : item?.registrar?.name
  }))
   }catch(error){
    showError(error.message)
    console.log(error)
   }finally{

   }
};


