const logs = ref([])
const logsLoading = ref(false)
const newMessage = ref('')
const replyingTo = ref(null)
const getLogs = async () => {
  logsLoading.value = true
  logs.value = []
  try {
    const response = await axiosInstance.get(`logs?source=LPO&source_id=${route.params.approval_list_id}`)
    logs.value = response.data
  } catch (error) {
    showError(error.message)
  } finally {
    logsLoading.value = false
  }
}




onMounted(async () => {
  await getApprovalItems();
  // await getApprovalGroup(); // Now uses group_id from items
  getLogs();
  
  // Auto-load first approval chain if items exist
  if (items.value.length > 0) {
    getApprovalChain(items.value[0]);
  }

  if (approvalModal.value) {
    onHidden = () => {
      localChecked.value = false;
      spinner.value = false;
    };
    approvalModal.value.addEventListener('hidden.bs.modal', onHidden);
  }
});




onBeforeUnmount(() => {
  if (approvalModal.value && onHidden) {
    approvalModal.value.removeEventListener('hidden.bs.modal', onHidden);
  }
});
